+import prismaMock from '../prisma-mock';
+import {
+  deleteComment,
+  getCommentsByArticle,
+} from '../../app/routes/article/article.service';
+
+describe('ArticleService', () => {
+  describe('deleteComment (soft delete)', () => {
+    const commentId = 123;
+    const authorId = 456;
+
+    test('should set deletedAt and keep the row', async () => {
+      // Given
+      // When
+      prismaMock.comment.findFirst.mockResolvedValue({
+        author: { id: authorId, username: 'RealWorld' },
+      } as any);
+      prismaMock.comment.update.mockResolvedValue({} as any);
+
+      // Then
+      await expect(deleteComment(commentId, authorId)).resolves.toBeUndefined();
+      expect(prismaMock.comment.update).toHaveBeenCalledWith({
+        where: { id: commentId },
+        data: { deletedAt: expect.any(Date) },
+      });
+      expect(prismaMock.comment.delete).not.toHaveBeenCalled();
+    });
+
+    test('should look up only live comments by id and by the current author', async () => {
+      // Given
+      // When
+      prismaMock.comment.findFirst.mockResolvedValue({
+        author: { id: authorId, username: 'RealWorld' },
+      } as any);
+      prismaMock.comment.update.mockResolvedValue({} as any);
+
+      // Then
+      await deleteComment(commentId, authorId);
+      expect(prismaMock.comment.findFirst).toHaveBeenCalledWith(
+        expect.objectContaining({
+          where: {
+            id: commentId,
+            deletedAt: null,
+            author: { id: authorId },
+          },
+        }),
+      );
+    });
+
+    test('should reject with 404 when the comment belongs to someone else', async () => {
+      // Given
+      const otherUserId = 789;
+
+      // When
+      // The lookup filters by author, so another user's comment is not found.
+      prismaMock.comment.findFirst.mockResolvedValue(null as any);
+
+      // Then
+      await expect(deleteComment(commentId, otherUserId)).rejects.toMatchObject({
+        errorCode: 404,
+      });
+      expect(prismaMock.comment.update).not.toHaveBeenCalled();
+    });
+
+    test('should reject with 404 when the comment is already deleted', async () => {
+      // Given
+      // When
+      // The lookup filters on deletedAt: null, so a deleted comment is not found.
+      prismaMock.comment.findFirst.mockResolvedValue(null as any);
+
+      // Then
+      await expect(deleteComment(commentId, authorId)).rejects.toMatchObject({
+        errorCode: 404,
+      });
+      expect(prismaMock.comment.findFirst).toHaveBeenCalledWith(
+        expect.objectContaining({
+          where: expect.objectContaining({ deletedAt: null }),
+        }),
+      );
+      expect(prismaMock.comment.update).not.toHaveBeenCalled();
+    });
+  });
+
+  describe('getCommentsByArticle (soft delete)', () => {
+    const slug = 'How-to-train-your-dragon';
+    const viewerId = 456;
+
+    test('should leave out comments with a deletedAt value', async () => {
+      // Given
+      // When
+      prismaMock.article.findUnique.mockResolvedValue({ comments: [] } as any);
+
+      // Then
+      await getCommentsByArticle(slug, viewerId);
+      expect(prismaMock.article.findUnique).toHaveBeenCalledWith(
+        expect.objectContaining({
+          include: {
+            comments: expect.objectContaining({
+              where: expect.objectContaining({ deletedAt: null }),
+            }),
+          },
+        }),
+      );
+    });
+
+    test('should return the live comments the database returns, with the author mapped', async () => {
+      // Given
+      const liveComment = {
+        id: 1,
+        createdAt: new Date(),
+        updatedAt: new Date(),
+        body: 'still here',
+        author: {
+          username: 'RealWorld',
+          bio: null,
+          image: null,
+          followedBy: [{ id: viewerId }],
+        },
+      };
+
+      // When
+      prismaMock.article.findUnique.mockResolvedValue({ comments: [liveComment] } as any);
+
+      // Then
+      const result = await getCommentsByArticle(slug, viewerId);
+      expect(result).toEqual([
+        expect.objectContaining({
+          id: 1,
+          body: 'still here',
+          author: {
+            username: 'RealWorld',
+            bio: null,
+            image: null,
+            following: true,
+          },
+        }),
+      ]);
+    });
+  });
+});

